sections.css:
.bcn-mkt-nav {
  position: absolute;
  top: 16px;
  left: 16px;
  right: 16px;
  z-index: 100;
  block-size: 56px;
  padding-inline: var(--spacing-500);
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: #ffffff0d;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: var(--radius-200);
}
.bcn-mkt-nav__logo {
  display: flex;
  align-items: center;
  gap: var(--spacing-250);
  text-decoration: none;
}
.bcn-mkt-nav__logo svg {
  inline-size: 22px;
  block-size: 32px;
}
.bcn-mkt-nav__wordmark {
  font-size: 1.1rem;
  font-weight: var(--font-weight-bold);
  letter-spacing: -0.02em;
  color: #fff;
}
.bcn-mkt-nav__login {
  display: inline-flex;
  align-items: center;
  padding: var(--spacing-150) var(--spacing-400);
  font-size: var(--type-size-200);
  font-weight: var(--font-weight-medium);
  color: #fff;
  background: transparent;
  border: 1px solid rgba(255, 255, 255, 0.4);
  border-radius: var(--radius-100);
  text-decoration: none;
  transition:
    background 0.15s ease,
    border-color 0.15s ease;
}

.esa-icon {
  --_icon-size: var(--icon-size-md, var(--icon-size-medium, 20px));
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--_icon-size);
  height: var(--_icon-size);
  line-height: 1;
  color: inherit;
}
.esa-icon--sm {
  --_icon-size: var(--icon-size-sm, var(--icon-size-small, 16px));
}
.esa-icon svg {
  display: block;
  width: var(--_icon-size);
  height: var(--_icon-size);
}
.esa-icon--xl {
  --_icon-size: var(--icon-size-xl, 28px);
}
.esa-icon--lg {
  --_icon-size: var(--icon-size-lg, var(--icon-size-large, 24px));
}
.esa-icon--md {
  --_icon-size: var(--icon-size-md, var(--icon-size-medium, 20px));
}
.bcn-mkt-hero {
  position: relative;
  overflow: hidden;
  padding: 120px 0 96px;
  background-image:
    linear-gradient(180deg, #002832d9, #003c46b3 40%, #005862d9), var(--_hero-image);
  background-size: cover;
  background-position: center 30%;
}
.bcn-mkt-hero__inner {
  max-inline-size: 1600px;
  margin-inline: auto;
  padding-inline: var(--spacing-500);
  text-align: center;
  position: relative;
  z-index: 1;
}
.bcn-mkt-hero__headline {
  margin: 0 0 var(--spacing-500);
  font-family: var(--font-decorative, var(--font-sans));
  font-size: var(--type-size-1000);
  font-weight: var(--font-weight-bold);
  line-height: 1.15;
  color: #fff;
}
.bcn-mkt-hero__sub {
  margin: 0 auto var(--spacing-600);
  max-inline-size: 840px;
  font-size: var(--type-size-400);
  font-weight: var(--font-weight-medium);
  color: #ffffffd9;
  line-height: var(--line-height-relaxed, 1.75);
  text-wrap: pretty;
}
.bcn-mkt-hero__ctas {
  display: flex;
  gap: var(--spacing-300);
  justify-content: center;
  flex-wrap: wrap;
}
.bcn-mkt-hero__btn {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-200);
  padding: var(--spacing-400) var(--spacing-600);
  font-size: var(--type-size-300);
  font-weight: var(--font-weight-semibold);
  border-radius: var(--radius-200);
  border: 1px solid transparent;
  text-decoration: none;
  transition:
    background 0.15s ease,
    border-color 0.15s ease;
}
.bcn-mkt-hero__btn--white {
  background: #fff;
  color: var(--color-primary);
  border-color: #fff;
}
.bcn-mkt-hero__btn--ghost {
  background: transparent;
  color: #fff;
  border-color: #fff6;
}
.bcn-mkt-hero__badge {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-200);
  margin-block-start: var(--spacing-700);
  font-size: var(--type-size-150);
  color: #fff9;
}
[data-reveal].is-visible {
  opacity: 1;
  transform: translateY(0);
}

.esa-icon {
  --_icon-size: var(--icon-size-md, var(--icon-size-medium, 20px));
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--_icon-size);
  height: var(--_icon-size);
  line-height: 1;
  color: inherit;
}
.esa-icon--sm {
  --_icon-size: var(--icon-size-sm, var(--icon-size-small, 16px));
}
.esa-icon svg {
  display: block;
  width: var(--_icon-size);
  height: var(--_icon-size);
}
.esa-icon--xl {
  --_icon-size: var(--icon-size-xl, 28px);
}
.esa-icon--lg {
  --_icon-size: var(--icon-size-lg, var(--icon-size-large, 24px));
}
.esa-icon--md {
  --_icon-size: var(--icon-size-md, var(--icon-size-medium, 20px));
}
.bcn-mkt-section {
  --_section-pad: clamp(48px, 8vw, 96px);
  padding-block: var(--_section-pad);
}
.bcn-mkt-section--white {
  background: var(--color-surface);
}
.bcn-mkt-section__inner {
  max-inline-size: 1100px;
  margin-inline: auto;
  padding-inline: var(--spacing-500);
}
.bcn-scale {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-700);
  align-items: center;
}
.bcn-section-intro {
  margin-block-end: var(--spacing-700);
}
.bcn-section-intro__eyebrow {
  display: block;
  font-size: 12px;
  font-weight: var(--font-weight-semibold);
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--color-text-tertiary);
  margin-block-end: var(--spacing-300);
}
.bcn-section-intro__headline {
  margin: 0 0 var(--spacing-400);
  font-family: var(--font-decorative, var(--font-sans));
  font-size: var(--type-size-700);
  font-weight: var(--font-weight-bold);
  line-height: var(--line-height-tight, 1.25);
  color: var(--color-text-primary);
  text-wrap: balance;
}
.bcn-section-intro__accent {
  inline-size: 48px;
  block-size: 4px;
  background: var(--color-primary);
  border-radius: var(--radius-full, 9999px);
  margin-block-end: var(--spacing-400);
}
.bcn-section-intro__subtext {
  margin: 0;
  font-size: var(--type-size-300);
  color: var(--color-text-secondary);
  max-inline-size: 820px;
  line-height: var(--line-height-relaxed, 1.75);
  text-wrap: balance;
}
.bcn-scale__stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-500);
}
.bcn-scale__stat {
  display: flex;
  align-items: flex-start;
  gap: var(--spacing-400);
}
.bcn-scale__icon {
  display: inline-flex;
  color: var(--color-primary);
  margin-block-start: 2px;
  flex-shrink: 0;
}
.bcn-scale__value {
  font-family: var(--font-decorative, var(--font-sans));
  font-size: var(--type-size-500);
  font-weight: var(--font-weight-bold);
  line-height: 1;
  margin-block-end: var(--spacing-100);
  color: var(--color-text-primary);
}
.bcn-scale__label {
  font-size: var(--type-size-150);
  color: var(--color-text-secondary);
  line-height: var(--line-height-normal, 1.5);
}
.bcn-scale__image {
  border-radius: var(--radius-200);
  overflow: hidden;
}
.bcn-scale__image img {
  inline-size: 100%;
  block-size: 100%;
  object-fit: cover;
  min-block-size: 400px;
}
.bcn-mkt-section--light {
  background: var(--color-surface-sunken, var(--color-gray-2));
}
.bcn-section-intro--center {
  text-align: center;
}
.bcn-section-intro--center .bcn-section-intro__accent {
  margin-inline: auto;
}
.bcn-section-intro--center .bcn-section-intro__subtext {
  margin-inline: auto;
}
.bcn-mkt-section--forest {
  color: #fff;
  background:
    linear-gradient(160deg, #02140af0, #052312eb 40%, #08321ce6),
    var(--_forest-image) center / cover no-repeat;
}
.bcn-section-intro--on-dark .bcn-section-intro__eyebrow {
  color: #fff9;
}
.bcn-section-intro--on-dark .bcn-section-intro__headline {
  color: #fff;
}
.bcn-section-intro--on-dark .bcn-section-intro__accent {
  background: #fff;
}
.bcn-section-intro--on-dark .bcn-section-intro__subtext {
