}
.bcn-section-intro--center .bcn-section-intro__subtext {
  margin-inline: auto;
}
.bcn-contrast {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-600);
}
.bcn-contrast__card {
  border-radius: var(--radius-200);
  padding: var(--spacing-600);
  border: 1px solid var(--color-border);
  overflow: hidden;
}
.bcn-contrast__card--before {
  background: var(--color-danger-subtle);
  border-color: var(--color-danger-border);
}
.bcn-contrast__bleed {
  margin: calc(-1 * var(--spacing-600)) calc(-1 * var(--spacing-600)) var(--spacing-500);
}
.bcn-contrast__bleed img {
  inline-size: 100%;
  block-size: 200px;
  object-fit: cover;
  display: block;
}
.bcn-contrast__title {
  display: flex;
  align-items: center;
  gap: var(--spacing-200);
  margin-block-end: var(--spacing-400);
  font-size: var(--type-size-400);
  font-weight: var(--font-weight-semibold);
}
.bcn-contrast__card--before .bcn-contrast__title {
  color: var(--color-danger-strong);
}
.bcn-contrast__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: var(--spacing-300);
}
.bcn-contrast__item {
  display: flex;
  align-items: flex-start;
  gap: var(--spacing-300);
  font-size: var(--type-size-200);
  line-height: var(--line-height-normal, 1.5);
}
.bcn-contrast__glyph {
  display: inline-flex;
  flex-shrink: 0;
  margin-block-start: 2px;
}
.bcn-contrast__card--before .bcn-contrast__glyph {
  color: var(--color-danger);
}
.bcn-contrast__card--after {
  background: var(--color-success-subtle);
  border-color: var(--color-success-border);
}
.bcn-contrast__mock {
  background: #292929;
  padding: var(--spacing-300);
  font-size: 12px;
  color: #bdbdbd;
  min-block-size: 200px;
  display: flex;
  flex-direction: column;
}
.bcn-contrast__mock-bar {
  display: flex;
  align-items: center;
  gap: var(--spacing-200);
  padding: var(--spacing-200) var(--spacing-300);
  background: #ffffff0f;
  border-radius: var(--radius-100);
  margin-block-end: var(--spacing-300);
  font-weight: var(--font-weight-medium);
  font-size: 11px;
  color: #989898;
}
.bcn-contrast__mock-dot {
  inline-size: 8px;
  block-size: 8px;
  border-radius: 50%;
  background: var(--color-primary);
}
.bcn-contrast__mock-row {
  display: flex;
  align-items: center;
  gap: var(--spacing-300);
  padding: var(--spacing-200) var(--spacing-300);
  border-block-end: 1px solid rgba(255, 255, 255, 0.06);
  font-size: 11px;
}
.bcn-contrast__mock-status {
  inline-size: 8px;
  block-size: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}
.bcn-contrast__mock-status.is-done {
  background: #4ade80;
}
.bcn-contrast__mock-row span:nth-child(2) {
  flex: 1;
  color: #fff;
}
.bcn-contrast__mock-badge {
  font-size: 10px;
  font-weight: var(--font-weight-semibold);
  padding: 2px 8px;
  border-radius: var(--radius-full, 9999px);
  white-space: nowrap;
}
.bcn-contrast__mock-badge.is-done {
  background: #4ade8026;
  color: #4ade80;
}
.bcn-contrast__mock-status.is-active {
  background: #f9a134;
}
.bcn-contrast__mock-badge.is-active {
  background: #f9a13426;
  color: #f9a134;
}
.bcn-contrast__mock-status.is-pending {
  background: #7c7c7c;
}
.bcn-contrast__mock-badge.is-pending {
  background: #ffffff0f;
  color: #989898;
}
.bcn-contrast__card--after .bcn-contrast__title {
  color: var(--color-success-strong);
}
.bcn-contrast__card--after .bcn-contrast__glyph {
  color: var(--color-success);
}
